          setProgress(run.progress || []);
          await new Promise((resolve, reject) => { const abort = () => { clearTimeout(timer); reject(controller.signal.reason); }; const timer = setTimeout(() => { controller.signal.removeEventListener("abort", abort); resolve(); }, 350); controller.signal.addEventListener("abort", abort, { once: true }); });
