      {[["粗体", "bold", "toggleBold"], ["斜体", "italic", "toggleItalic"], ["下划线", "underline", "toggleUnderline"], ["删除线", "strike", "toggleStrike"], ["无序列表", "bulletList", "toggleBulletList"], ["有序列表", "orderedList", "toggleOrderedList"]].map(([label, icon, command]) => <Button key={icon} className="dm-format-button" aria-label={label} title={label} aria-pressed={!!format[icon]} disabled={!rich} onMouseDown={(e) => e.preventDefault()} onClick={() => editor.current?.chain().focus()[command]().run()}><Icon name={icon} size={17} /></Button>)}
