function MiniCalendar({ value, firstDay, timeZone, onSelect, onMonth }) {
  const selected = DateTime.fromISO(value, { zone: timeZone }), month = selected.startOf("month"), start = month.minus({ days: (month.weekday % 7 - firstDay + 7) % 7 }), today = DateTime.now().setZone(timeZone).toISODate();
  return <div className="dm-mini-calendar"><header><strong>{month.toFormat("yyyy年M月")}</strong><Button aria-label="小月历上一月" onClick={() => onMonth(month.minus({ months: 1 }).toISODate())}><Icon name="back" size={15} /></Button><Button aria-label="小月历下一月" onClick={() => onMonth(month.plus({ months: 1 }).toISODate())}><Icon name="next" size={15} /></Button></header><div className="dm-mini-grid">{Array.from({ length: 7 }, (_, i) => <span className="dm-mini-weekday" key={`weekday-${i}`}>{["日", "一", "二", "三", "四", "五", "六"][(firstDay + i) % 7]}</span>)}{Array.from({ length: 42 }, (_, i) => { const day = start.plus({ days: i }), iso = day.toISODate(); return <button type="button" key={iso} aria-label={`跳转到 ${iso}`} aria-current={iso === today ? "date" : undefined} className={`${day.month !== month.month ? "outside" : ""} ${iso === value ? "chosen" : ""}`} onClick={() => onSelect(iso)}>{day.day}</button>; })}</div></div>;
}
