  useEffect(() => { setSelectedIds((current) => { const known = lastData.current.calendars.map((item) => item.id); return [...current.filter((id) => state.calendars.some((item) => item.id === id)), ...state.calendars.filter((item) => !known.includes(item.id)).map((item) => item.id)]; }); }, [state.calendars]);
  useEffect(() => {
    const c = new Calendar(ref.current, {
      plugins: [dayGridPlugin, timeGridPlugin, listPlugin, interactionPlugin, luxonPlugin], locale: zhLocale, timeZone: settings.calendarTimeZone, initialView: settings.calendarView, initialDate: navigation?.page === "calendar" ? navigation.date : undefined, firstDay: settings.firstDay,
      height: "100%", expandRows: true, fixedWeekCount: false, dayMaxEvents: true, dayCellContent: (info) => info.dayNumberText.replace(/日$/, ""), headerToolbar: { left: "today prev,next title", center: "", right: "dayGridMonth,timeGridWeek,timeGridDay,listWeek" }, editable: true, selectable: true, eventDisplay: "block",
      datesSet: (info) => setCalendarDate(DateTime.fromJSDate(info.view.calendar.getDate(), { zone: preferences.current.calendarTimeZone }).toISODate()),
      select: (info) => setModal({ type: "event", value: { start: info.startStr, end: info.endStr, allDay: info.allDay, calendarId: selected.current[0] || "default" } }),
      eventDidMount: (info) => { info.el.dataset.mailEntity = info.event.extendedProps.source.eventId || info.event.id; info.el.dataset.agentSelected = String(info.el.dataset.mailEntity === navigationRef.current?.entityId); info.el.title = `${info.event.title} · ${info.event.startStr}${eventHasEnded(info.event.extendedProps.source, { timeZone: preferences.current.calendarTimeZone }) ? " · 已结束" : ""}`; },
      eventClick: (info) => setModal({ type: "event", value: info.event.extendedProps.original }),
      eventDrop: (info) => run(async () => { try { const e = info.event.extendedProps.original; await act({ action: "events.save", event: { ...e, start: info.event.startStr, end: info.event.endStr, ...(e.rrule ? { id: undefined, revision: undefined, recurrenceId: e.start, rrule: "" } : {}) } }); } catch { info.revert(); } }),
      eventResize: (info) => run(async () => { try { const e = info.event.extendedProps.original; await act({ action: "events.save", event: { ...e, start: info.event.startStr, end: info.event.endStr } }); } catch { info.revert(); } }),
      events: async (info, success, failure) => { if (!selected.current.length) return success([]); try { const events = await request({ action: "events.list", start: info.startStr, end: info.endStr, calendarId: selected.current.length === 1 ? selected.current[0] : undefined }); success(events.filter((event) => selected.current.includes(event.calendarId)).map((e) => ({ id: e.id, title: e.title, start: e.start, end: e.end, allDay: e.allDay, ...eventAppearance(e, calendars.current, { timeZone: preferences.current.calendarTimeZone }), extendedProps: { original: editableEvent(e), source: e } }))); } catch (e) { failure(e); } },
    });
    c.render(); calendar.current = c;
    let frame; const observer = new ResizeObserver(() => { cancelAnimationFrame(frame); frame = requestAnimationFrame(() => c.updateSize()); }); observer.observe(ref.current.parentElement);
    const timer = setInterval(() => c.batchRendering(() => { for (const event of c.getEvents()) { const appearance = eventAppearance(event.extendedProps.source, calendars.current, { timeZone: preferences.current.calendarTimeZone }); for (const [key, value] of Object.entries(appearance)) if (event[key] !== value) event.setProp(key, value); } }), 30000);
    return () => { clearInterval(timer); observer.disconnect(); cancelAnimationFrame(frame); c.destroy(); calendar.current = null; };
  }, []);
  useEffect(() => { calendar.current?.setOption("timeZone", settings.calendarTimeZone); calendar.current?.setOption("firstDay", settings.firstDay); }, [settings.calendarTimeZone, settings.firstDay]);
  useEffect(() => { calendar.current?.changeView(settings.calendarView); }, [settings.calendarView]);
  useEffect(() => { if (navigation?.page !== "calendar") return; if (navigation.calendarId && state.calendars.some((item) => item.id === navigation.calendarId)) setSelectedIds((ids) => ids.includes(navigation.calendarId) ? ids : [...ids, navigation.calendarId]); if (navigation.date) calendar.current?.gotoDate(navigation.date); }, [navigation?.id]);
  useEffect(() => { const previous = lastData.current; if (previous.events !== state.events || previous.calendars !== state.calendars || previous.selectionKey !== selectionKey) calendar.current?.refetchEvents(); lastData.current = { events: state.events, calendars: state.calendars, selectionKey }; }, [state.events, state.calendars, selectionKey]);
