  const zone = state.settings?.eventTimeZone || DEFAULT_SETTINGS.eventTimeZone;
  const defaults = { title: "", start: DateTime.now().setZone(zone).plus({ hours: 1 }).startOf("hour").toISO(), end: DateTime.now().setZone(zone).plus({ hours: 2 }).startOf("hour").toISO(), timeZone: zone, calendarId: "default", reminderMinutes: state.settings?.eventReminder ?? 15, description: "", location: "", rrule: "", color: value?.id || value?.recurrenceId ? undefined : "#22dbf4" };
  const [form, setForm] = useState({ ...defaults, ...value }), [attendees, setAttendees] = useState(addr(value?.attendees)), [accountId, setAccountId] = useState(state.accounts.find((a) => !a.local)?.id || "");
  const change = (key, v) => setForm({ ...form, [key]: v });
  const time = (key) => form.allDay ? form[key]?.slice(0, 10) : DateTime.fromISO(form[key], { zone: form.timeZone }).toFormat("yyyy-MM-dd'T'HH:mm");
